insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('harira', '{"en":"Harira (with beef)","fr":"Harira (au bœuf)","ar":"الحريرة (باللحم)"}'::jsonb, true, 'soup', array['dinner','lunch']::text[], 6, '{"en":"1 bowl (≈350 ml)","fr":"1 bol (≈350 ml)","ar":"زلافة واحدة (≈350 مل)"}'::jsonb, 20, 75, true, null, null, null, '{"en":["Soak the chickpeas overnight, then drain.","Cut the meat into small cubes. In a large pot, cook meat, chopped onion, celery, herbs, spices and oil for 5 minutes.","Add blended tomatoes, tomato paste, chickpeas, lentils and 2.5 L of water. Simmer 60 minutes.","Whisk the flour with 300 ml cold water and pour slowly while stirring to thicken (tadouira).","Add vermicelli and cook 8–10 minutes. Serve with lemon juice."],"fr":["Faire tremper les pois chiches la veille, puis égoutter.","Couper la viande en petits dés. Dans une grande marmite, faire revenir viande, oignon, céleri, herbes, épices et huile 5 minutes.","Ajouter les tomates mixées, le concentré, les pois chiches, les lentilles et 2,5 L d’eau. Laisser mijoter 60 minutes.","Délayer la farine dans 300 ml d’eau froide et verser doucement en remuant pour épaissir (tadouira).","Ajouter les vermicelles et cuire 8 à 10 minutes. Servir avec du jus de citron."],"ar":["انقعي الحمص من الليلة السابقة ثم صفيه.","قطعي اللحم مكعبات صغيرة. في قدر كبير، شوحي اللحم مع البصل والكرافس والقزبور والمعدنوس والتوابل والزيت لمدة 5 دقائق.","أضيفي الطماطم المطحونة ومعجون الطماطم والحمص والعدس و2.5 لتر من الماء، واتركيها تطهى 60 دقيقة.","اخلطي الدقيق مع 300 مل ماء بارد (التدويرة) وصبيها تدريجيا مع التحريك.","أضيفي الشعرية واتركيها 8 إلى 10 دقائق. تقدم مع الحامض."]}'::jsonb);
