insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('bissara', '{"en":"Bissara (fava bean soup)","fr":"Bissara (soupe de fèves)","ar":"البيصارة"}'::jsonb, true, 'soup', array['breakfast','dinner','lunch']::text[], 4, '{"en":"1 bowl (≈300 ml)","fr":"1 bol (≈300 ml)","ar":"زلافة (≈300 مل)"}'::jsonb, 10, 50, true, null, null, null, '{"en":["Soak peeled dried fava beans for a few hours, then rinse.","Cook with garlic and 1.5 L of water for about 45 minutes until very soft.","Blend until smooth, add salt and adjust thickness with hot water.","Serve with olive oil, cumin, paprika and a little lemon juice."],"fr":["Faire tremper les fèves sèches décortiquées quelques heures, puis rincer.","Cuire avec l’ail et 1,5 L d’eau environ 45 minutes jusqu’à ce qu’elles soient très tendres.","Mixer finement, saler et ajuster la consistance avec de l’eau chaude.","Servir avec huile d’olive, cumin, paprika et un peu de citron."],"ar":["انقعي الفول اليابس المقشر بضع ساعات ثم اغسليه.","اطهيه مع الثوم و1.5 لتر ماء حوالي 45 دقيقة حتى يصبح طريا جدا.","اطحنيه جيدا وأضيفي الملح وعدلي الكثافة بالماء الساخن.","تقدم مع زيت الزيتون والكمون والتحميرة وقليل من الحامض."]}'::jsonb);
