insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('zaalouk', '{"en":"Zaalouk (eggplant & tomato)","fr":"Zaalouk (aubergine et tomate)","ar":"الزعلوك"}'::jsonb, true, 'salad', array['lunch','dinner','snack']::text[], 4, '{"en":"1 small plate (≈200 g)","fr":"1 petite assiette (≈200 g)","ar":"صحن صغير (≈200 غ)"}'::jsonb, 15, 30, true, null, null, null, '{"en":["Peel the eggplant in stripes and cut into cubes; steam or boil 15 minutes.","Peel and grate the tomatoes.","Cook tomatoes, garlic, oil and spices 10 minutes, add the eggplant and mash.","Cook until thick, add herbs. Serve warm or cold."],"fr":["Éplucher l’aubergine en bandes et la couper en dés ; cuire à la vapeur ou à l’eau 15 minutes.","Peler et râper les tomates.","Cuire tomates, ail, huile et épices 10 minutes, ajouter l’aubergine et écraser.","Laisser réduire, ajouter les herbes. Servir tiède ou froid."],"ar":["قشري الباذنجان على شكل خطوط وقطعيه مكعبات، ثم اطهيه بالبخار أو في الماء 15 دقيقة.","قشري الطماطم واحككيها.","اطهي الطماطم مع الثوم والزيت والتوابل 10 دقائق، ثم أضيفي الباذنجان واهرسيه.","اتركيه حتى يتعقد وأضيفي الأعشاب. يقدم دافئا أو باردا."]}'::jsonb);
