insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('taktouka', '{"en":"Taktouka (pepper & tomato)","fr":"Taktouka (poivrons et tomates)","ar":"التكتوكة"}'::jsonb, true, 'salad', array['lunch','dinner','snack']::text[], 4, '{"en":"1 small plate (≈200 g)","fr":"1 petite assiette (≈200 g)","ar":"صحن صغير (≈200 غ)"}'::jsonb, 20, 25, true, null, null, null, '{"en":["Grill the peppers until the skin blackens, cover 10 minutes, then peel and dice.","Cook grated tomatoes with garlic, oil and spices for 10 minutes.","Add peppers and cook 10 more minutes until thick. Finish with coriander."],"fr":["Griller les poivrons jusqu’à ce que la peau noircisse, couvrir 10 minutes, peler et couper en dés.","Cuire les tomates râpées avec l’ail, l’huile et les épices 10 minutes.","Ajouter les poivrons et cuire encore 10 minutes. Finir avec la coriandre."],"ar":["اشوي الفلفل حتى يسود جلده، غطيه 10 دقائق ثم قشريه وقطعيه.","اطهي الطماطم المحكوكة مع الثوم والزيت والتوابل 10 دقائق.","أضيفي الفلفل واتركيه 10 دقائق أخرى حتى يتعقد، ثم القزبور."]}'::jsonb);
