insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('couscous_beef', '{"en":"Couscous with seven vegetables (beef)","fr":"Couscous aux sept légumes (bœuf)","ar":"كسكس بسبع خضاري (باللحم)"}'::jsonb, true, 'main', array['lunch']::text[], 6, '{"en":"1 plate (≈450 g)","fr":"1 assiette (≈450 g)","ar":"صحن (≈450 غ)"}'::jsonb, 30, 90, false, null, null, null, '{"en":["Soak chickpeas overnight.","In the base of a couscoussier, brown meat with onion, tomato, oil and spices; add 2 L water and chickpeas; cook 45 minutes.","Add carrots, turnips and cabbage; 15 minutes later add zucchini and pumpkin.","Steam the couscous over the broth three times, working in a little water and the butter between steamings.","Arrange couscous, meat and vegetables on a plate; serve broth on the side."],"fr":["Faire tremper les pois chiches la veille.","Dans le bas du couscoussier, faire revenir la viande avec oignon, tomate, huile et épices ; ajouter 2 L d’eau et les pois chiches ; cuire 45 minutes.","Ajouter carottes, navets et chou ; 15 minutes plus tard, courgettes et potiron.","Cuire la semoule à la vapeur trois fois, en l’aérant avec un peu d’eau et le beurre entre chaque passage.","Dresser semoule, viande et légumes ; servir le bouillon à part."],"ar":["انقعي الحمص من الليلة السابقة.","في أسفل الكسكاس، شوحي اللحم مع البصل والطماطم والزيت والتوابل، ثم أضيفي 2 لتر ماء والحمص واتركيه 45 دقيقة.","أضيفي الجزر واللفت والكرنب، وبعد 15 دقيقة الكوسة والكرعة.","فوري الكسكس فوق المرق ثلاث مرات مع تفتيله بقليل من الماء والزبدة بين كل تفويرة.","رتبي الكسكس واللحم والخضر في الطبق، وقدمي المرق جانبا."]}'::jsonb);
