insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tagine_chicken_olives', '{"en":"Chicken tagine with lemon & olives","fr":"Tajine de poulet au citron et olives","ar":"طاجين الدجاج بالحامض والزيتون"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 portion (≈300 g)","fr":"1 portion (≈300 g)","ar":"حصة (≈300 غ)"}'::jsonb, 15, 60, false, null, null, '{"en":"Preserved lemon is calculated with the USDA value for fresh lemon (no preserved-lemon reference exists).","fr":"Le citron confit est calculé avec la valeur USDA du citron frais (pas de référence pour le citron confit).","ar":"الحامض المصير محسوب بقيمة الحامض الطري لعدم وجود مرجع له."}'::jsonb, '{"en":["Marinate chicken with grated onion, garlic, spices, herbs and oil for 30 minutes (or longer).","Cook covered on low heat with 200 ml water for 45 minutes, turning once.","Add olives and lemon pieces and cook 10 more minutes until the sauce thickens."],"fr":["Mariner le poulet avec oignon râpé, ail, épices, herbes et huile 30 minutes (ou plus).","Cuire à couvert à feu doux avec 200 ml d’eau 45 minutes, en retournant une fois.","Ajouter olives et citron, cuire encore 10 minutes jusqu’à ce que la sauce réduise."],"ar":["تبلي الدجاج بالبصل المحكوك والثوم والتوابل والأعشاب والزيت 30 دقيقة أو أكثر.","اطهيه مغطى على نار هادئة مع 200 مل ماء لمدة 45 دقيقة مع قلبه مرة.","أضيفي الزيتون والحامض واتركيه 10 دقائق حتى تتعقد المرقة."]}'::jsonb);
