insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tagine_beef_prunes', '{"en":"Beef tagine with prunes","fr":"Tajine de bœuf aux pruneaux","ar":"طاجين اللحم بالبرقوق"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 6, '{"en":"1 portion (≈250 g)","fr":"1 portion (≈250 g)","ar":"حصة (≈250 غ)"}'::jsonb, 15, 120, false, null, null, null, '{"en":["Cook meat with onion, spices, oil, butter and 500 ml water, covered, about 1 h 30 until tender.","Simmer prunes separately with a little sauce, the honey and cinnamon for 10 minutes.","Serve meat topped with prunes, toasted almonds and sesame."],"fr":["Cuire la viande avec oignon, épices, huile, beurre et 500 ml d’eau, à couvert, environ 1 h 30.","Faire mijoter les pruneaux avec un peu de sauce, le miel et la cannelle 10 minutes.","Servir la viande garnie de pruneaux, amandes grillées et sésame."],"ar":["اطهي اللحم مع البصل والتوابل والزيت والزبدة و500 مل ماء مغطى حوالي ساعة ونصف.","اطهي البرقوق على حدة مع قليل من المرق والعسل والقرفة 10 دقائق.","قدمي اللحم مزينا بالبرقوق واللوز المحمر والجنجلان."]}'::jsonb);
