insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tagine_kefta_eggs', '{"en":"Kefta tagine with tomato & eggs","fr":"Tajine de kefta aux tomates et œufs","ar":"طاجين الكفتة بالطماطم والبيض"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 portion (≈300 g)","fr":"1 portion (≈300 g)","ar":"حصة (≈300 غ)"}'::jsonb, 20, 30, false, null, null, null, '{"en":["Mix the meat with half the herbs, cumin, paprika and salt; shape small balls.","Cook grated tomatoes, onion, garlic, oil and spices for 15 minutes.","Add the meatballs, cover and cook 10 minutes.","Crack the eggs on top, cover and cook until set. Sprinkle with herbs."],"fr":["Mélanger la viande avec la moitié des herbes, cumin, paprika et sel ; former des boulettes.","Cuire tomates râpées, oignon, ail, huile et épices 15 minutes.","Ajouter les boulettes, couvrir et cuire 10 minutes.","Casser les œufs dessus, couvrir jusqu’à ce qu’ils prennent. Parsemer d’herbes."],"ar":["اخلطي اللحم المفروم مع نصف الأعشاب والكمون والتحميرة والملح، وشكلي كويرات صغيرة.","اطهي الطماطم المحكوكة مع البصل والثوم والزيت والتوابل 15 دقيقة.","أضيفي الكويرات وغطي الطاجين 10 دقائق.","اكسري البيض فوقها وغطيها حتى ينضج، ثم رشي الأعشاب."]}'::jsonb);
