insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tagine_vegetables', '{"en":"Vegetable tagine","fr":"Tajine de légumes","ar":"طاجين الخضر"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 portion (≈350 g)","fr":"1 portion (≈350 g)","ar":"حصة (≈350 غ)"}'::jsonb, 20, 50, true, null, null, null, '{"en":["Place sliced onion and tomato in the tagine with oil, spices and herbs.","Arrange potatoes, carrots, zucchini and peas on top; add 250 ml water.","Cover and cook on low heat 45–50 minutes. Add olives at the end."],"fr":["Disposer oignon et tomate émincés dans le tajine avec huile, épices et herbes.","Ranger pommes de terre, carottes, courgettes et petits pois ; ajouter 250 ml d’eau.","Couvrir et cuire à feu doux 45 à 50 minutes. Ajouter les olives à la fin."],"ar":["ضعي البصل والطماطم المقطعين في الطاجين مع الزيت والتوابل والأعشاب.","رتبي البطاطس والجزر والكوسة والجلبانة فوقها وأضيفي 250 مل ماء.","غطيه واتركيه على نار هادئة 45 إلى 50 دقيقة، والزيتون في الأخير."]}'::jsonb);
