insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tagine_fish', '{"en":"Fish tagine with chermoula","fr":"Tajine de poisson à la chermoula","ar":"طاجين الحوت بالشرمولة"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 portion (≈350 g)","fr":"1 portion (≈350 g)","ar":"حصة (≈350 غ)"}'::jsonb, 25, 40, false, null, null, null, '{"en":["Make chermoula: blend coriander, garlic, cumin, paprika, lemon juice, half the oil and salt.","Coat the fish with half the chermoula and let rest 20 minutes.","Layer sliced potatoes and carrots in the tagine, then tomatoes and peppers; add remaining chermoula and 150 ml water.","Cook 25 minutes, place the fish on top and cook 15 more minutes covered."],"fr":["Préparer la chermoula : mixer coriandre, ail, cumin, paprika, citron, la moitié de l’huile et le sel.","Enrober le poisson de la moitié de la chermoula, laisser reposer 20 minutes.","Disposer pommes de terre et carottes en rondelles, puis tomates et poivrons ; ajouter le reste de chermoula et 150 ml d’eau.","Cuire 25 minutes, poser le poisson et cuire encore 15 minutes à couvert."],"ar":["حضري الشرمولة: اخلطي القزبور والثوم والكمون والتحميرة والحامض ونصف الزيت والملح.","تبلي الحوت بنصف الشرمولة واتركيه 20 دقيقة.","رتبي البطاطس والجزر شرائح ثم الطماطم والفلفل، وأضيفي باقي الشرمولة و150 مل ماء.","اطهي 25 دقيقة، ثم ضعي الحوت فوقها واتركيه 15 دقيقة مغطى."]}'::jsonb);
