insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('rfissa', '{"en":"Rfissa (chicken, lentils & msemen)","fr":"Rfissa (poulet, lentilles et msemen)","ar":"الرفيسة"}'::jsonb, true, 'main', array['lunch']::text[], 6, '{"en":"1 plate (≈400 g)","fr":"1 assiette (≈400 g)","ar":"صحن (≈400 غ)"}'::jsonb, 40, 90, false, null, null, '{"en":"Fenugreek and ras el hanout are used in small amounts and are not in the reference database; their contribution is not counted.","fr":"Le fenugrec et le ras el hanout, en petites quantités, ne sont pas dans la base de référence ; ils ne sont pas comptés.","ar":"الحلبة ورأس الحانوت بكميات صغيرة غير موجودين في قاعدة البيانات ولم يتم حسابهما."}'::jsonb, '{"en":["Prepare thin msemen with the flour, semolina, salt, water and oil (see the msemen recipe), then tear into strips.","Cook chicken with sliced onions, spices, herbs, olive oil and 1.5 L water for 50 minutes.","Add the lentils and cook 30 more minutes.","Steam the msemen strips briefly, place them in a dish, and top with chicken, lentils and broth."],"fr":["Préparer des msemen fins avec farine, semoule, sel, eau et huile (voir la recette), puis les déchirer en lanières.","Cuire le poulet avec les oignons émincés, épices, herbes, huile d’olive et 1,5 L d’eau 50 minutes.","Ajouter les lentilles et cuire encore 30 minutes.","Réchauffer les lanières à la vapeur, les disposer dans un plat et napper de poulet, lentilles et bouillon."],"ar":["حضري مسمن رقيق بالدقيق والسميد والملح والماء والزيت ثم قطعيه شرائح.","اطهي الدجاج مع البصل المشرح والتوابل والأعشاب وزيت الزيتون و1.5 لتر ماء لمدة 50 دقيقة.","أضيفي العدس واتركيه 30 دقيقة أخرى.","فوري شرائح المسمن قليلا، وضعيها في الطبق ثم الدجاج والعدس والمرق فوقها."]}'::jsonb);
