insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('loubia', '{"en":"Loubia (white beans in tomato sauce)","fr":"Loubia (haricots blancs à la tomate)","ar":"اللوبيا"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 bowl (≈300 g)","fr":"1 bol (≈300 g)","ar":"زلافة (≈300 غ)"}'::jsonb, 10, 70, true, null, null, null, '{"en":["Soak the beans overnight and drain.","Put all ingredients in a pot with 1.2 L water.","Simmer 60–70 minutes until the beans are soft and the sauce is thick."],"fr":["Faire tremper les haricots la veille et égoutter.","Mettre tous les ingrédients dans une marmite avec 1,2 L d’eau.","Mijoter 60 à 70 minutes jusqu’à ce que les haricots soient tendres et la sauce épaisse."],"ar":["انقعي اللوبيا من الليلة السابقة وصفيها.","ضعي جميع المكونات في قدر مع 1.2 لتر ماء.","اتركيها 60 إلى 70 دقيقة حتى تنضج اللوبيا وتتعقد المرقة."]}'::jsonb);
