insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('adass', '{"en":"Moroccan lentils (adass)","fr":"Lentilles à la marocaine","ar":"العدس بالطريقة المغربية"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"1 bowl (≈300 g)","fr":"1 bol (≈300 g)","ar":"زلافة (≈300 غ)"}'::jsonb, 10, 40, true, null, null, null, '{"en":["Rinse the lentils.","Cook all ingredients with 1.2 L water for 35–40 minutes until creamy.","Adjust seasoning and serve with bread or alone."],"fr":["Rincer les lentilles.","Cuire tous les ingrédients avec 1,2 L d’eau 35 à 40 minutes.","Rectifier l’assaisonnement et servir."],"ar":["اغسلي العدس.","اطهي جميع المكونات مع 1.2 لتر ماء لمدة 35 إلى 40 دقيقة.","عدلي الملح وقدميه."]}'::jsonb);
