insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('moroccan_salad', '{"en":"Moroccan tomato & cucumber salad","fr":"Salade marocaine tomates-concombre","ar":"شلاضة مغربية"}'::jsonb, true, 'salad', array['lunch','dinner','snack']::text[], 4, '{"en":"1 bowl (≈230 g)","fr":"1 bol (≈230 g)","ar":"زلافة (≈230 غ)"}'::jsonb, 15, 0, true, null, null, null, '{"en":["Dice tomatoes, cucumber, onion and pepper finely.","Mix with chopped coriander, oil, lemon juice, cumin and salt just before serving."],"fr":["Couper finement tomates, concombre, oignon et poivron.","Mélanger avec coriandre, huile, citron, cumin et sel juste avant de servir."],"ar":["قطعي الطماطم والخيار والبصل والفلفل قطعا صغيرة.","اخلطيها مع القزبور والزيت والحامض والكمون والملح قبل التقديم."]}'::jsonb);
