insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('carrot_salad', '{"en":"Carrot salad with cumin","fr":"Salade de carottes au cumin","ar":"شلاضة الجزر بالكمون"}'::jsonb, true, 'salad', array['lunch','dinner','snack']::text[], 4, '{"en":"1 small plate (≈140 g)","fr":"1 petite assiette (≈140 g)","ar":"صحن صغير (≈140 غ)"}'::jsonb, 10, 15, true, null, null, null, '{"en":["Boil the sliced carrots with the garlic until just tender; drain.","Toss with oil, lemon juice, cumin, parsley and salt."],"fr":["Cuire les carottes en rondelles avec l’ail jusqu’à tendreté ; égoutter.","Mélanger avec huile, citron, cumin, persil et sel."],"ar":["اسلقي الجزر المقطع مع الثوم حتى ينضج قليلا ثم صفيه.","اخلطيه مع الزيت والحامض والكمون والمعدنوس والملح."]}'::jsonb);
