insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('beet_salad', '{"en":"Beetroot salad","fr":"Salade de betteraves","ar":"شلاضة الباربا"}'::jsonb, true, 'salad', array['lunch','dinner','snack']::text[], 4, '{"en":"1 small plate (≈145 g)","fr":"1 petite assiette (≈145 g)","ar":"صحن صغير (≈145 غ)"}'::jsonb, 10, 40, true, null, null, null, '{"en":["Boil the beets whole until tender (35–40 min), peel and dice.","Mix with chopped onion, parsley, oil, vinegar, cumin and salt."],"fr":["Cuire les betteraves entières jusqu’à tendreté (35–40 min), peler et couper en dés.","Mélanger avec oignon, persil, huile, vinaigre, cumin et sel."],"ar":["اسلقي الباربا كاملة حتى تنضج (35-40 دقيقة)، ثم قشريها وقطعيها.","اخلطيها مع البصل والمعدنوس والزيت والخل والكمون والملح."]}'::jsonb);
