insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('sardines_tomato', '{"en":"Sardines with tomato, onion & bread","fr":"Sardines, tomates, oignon et pain","ar":"سردين بالطماطم والبصل مع الخبز"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 2, '{"en":"1 plate (≈200 g)","fr":"1 assiette (≈200 g)","ar":"صحن (≈200 غ)"}'::jsonb, 10, 0, true, null, null, null, '{"en":["Drain the sardines.","Dice tomato and onion; mix with parsley, lemon juice and cumin.","Serve the sardines over the tomato mix with whole-wheat bread."],"fr":["Égoutter les sardines.","Couper tomate et oignon ; mélanger avec persil, citron et cumin.","Servir les sardines sur ce mélange avec du pain complet."],"ar":["صفي السردين من الزيت.","قطعي الطماطم والبصل واخلطيهما مع المعدنوس والحامض والكمون.","قدمي السردين فوق الخليط مع الخبز الكامل."]}'::jsonb);
