insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('msemen', '{"en":"Msemen (square pancakes)","fr":"Msemen (crêpes feuilletées)","ar":"المسمن"}'::jsonb, true, 'bread', array['breakfast','snack']::text[], 8, '{"en":"1 msemen (≈75 g)","fr":"1 msemen (≈75 g)","ar":"مسمنة واحدة (≈75 غ)"}'::jsonb, 40, 25, false, null, null, null, '{"en":["Knead flour, semolina, salt and about 280 ml warm water into a soft, smooth dough (10 minutes).","Divide into 8 balls, oil them and rest 10 minutes.","Spread each ball very thin on an oiled surface, brush with melted butter, sprinkle semolina and fold into a square.","Cook on a hot pan 2–3 minutes per side until golden."],"fr":["Pétrir farine, semoule, sel et environ 280 ml d’eau tiède jusqu’à obtenir une pâte souple (10 minutes).","Diviser en 8 boules, les huiler et laisser reposer 10 minutes.","Étaler chaque boule très finement sur un plan huilé, badigeonner de beurre fondu, saupoudrer de semoule et plier en carré.","Cuire à la poêle chaude 2 à 3 minutes de chaque côté."],"ar":["اعجني الدقيق والسميد والملح مع حوالي 280 مل ماء دافئ حتى تحصلي على عجين لين (10 دقائق).","قسميه إلى 8 كويرات، ادهنيها بالزيت واتركيها 10 دقائق.","افردي كل كويرة رقيقة جدا، ادهنيها بالزبدة الذائبة ورشي السميد ثم طويها على شكل مربع.","اطهيها في مقلاة ساخنة 2-3 دقائق لكل جهة."]}'::jsonb);
