insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('baghrir', '{"en":"Baghrir (plain)","fr":"Baghrir (nature)","ar":"البغرير (بدون إضافات)"}'::jsonb, true, 'bread', array['breakfast','snack']::text[], 12, '{"en":"1 baghrir (≈45 g)","fr":"1 baghrir (≈45 g)","ar":"بغريرة واحدة (≈45 غ)"}'::jsonb, 10, 30, false, null, null, '{"en":"Yeast and baking powder (a few grams) are not counted. Toppings are not included — see the honey & butter variation.","fr":"La levure et la levure chimique (quelques grammes) ne sont pas comptées. Garnitures non incluses — voir la variante miel-beurre.","ar":"الخميرة لم تحسب. الإضافات غير محسوبة — انظري وصفة البغرير بالعسل والزبدة."}'::jsonb, '{"en":["Blend semolina, flour, salt, sugar, yeast, baking powder and about 600 ml lukewarm water for 2 minutes.","Let the batter rest 30 minutes until bubbly.","Pour a ladle onto a hot non-stick pan and cook on one side only until the surface is full of holes and dry."],"fr":["Mixer semoule, farine, sel, sucre, levure, levure chimique et environ 600 ml d’eau tiède 2 minutes.","Laisser reposer 30 minutes jusqu’à formation de bulles.","Verser une louche dans une poêle antiadhésive chaude et cuire d’un seul côté jusqu’à ce que la surface soit pleine de trous et sèche."],"ar":["اخلطي السميد والدقيق والملح والسكر والخميرة والخميرة الكيميائية مع حوالي 600 مل ماء دافئ لمدة دقيقتين.","اتركي الخليط 30 دقيقة حتى تظهر الفقاعات.","صبي مغرفة في مقلاة ساخنة واطهيها من جهة واحدة حتى تمتلئ بالثقوب وتجف."]}'::jsonb);
