insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('khobz', '{"en":"Moroccan bread (khobz)","fr":"Pain marocain (khobz)","ar":"الخبز المغربي"}'::jsonb, true, 'bread', array['breakfast','lunch','dinner']::text[], 8, '{"en":"1/8 loaf (≈80 g)","fr":"1/8 de pain (≈80 g)","ar":"ثمن خبزة (≈80 غ)"}'::jsonb, 20, 25, true, null, null, '{"en":"Yeast (≈7 g) is not counted.","fr":"La levure (≈7 g) n’est pas comptée.","ar":"الخميرة (≈7 غ) غير محسوبة."}'::jsonb, '{"en":["Mix flours, salt, sugar, yeast, oil and about 330 ml warm water; knead 10 minutes.","Shape into 2 round flat loaves, cover and let rise 1 hour.","Prick with a fork and bake at 220 °C for 20–25 minutes."],"fr":["Mélanger farines, sel, sucre, levure, huile et environ 330 ml d’eau tiède ; pétrir 10 minutes.","Façonner 2 pains ronds et plats, couvrir et laisser lever 1 heure.","Piquer à la fourchette et cuire à 220 °C 20 à 25 minutes."],"ar":["اخلطي الدقيقين والملح والسكر والخميرة والزيت مع حوالي 330 مل ماء دافئ واعجنيه 10 دقائق.","شكلي خبزتين مستديرتين وغطيهما واتركيهما تختمران ساعة.","اثقبيهما بالشوكة واخبزيهما في 220 درجة لمدة 20 إلى 25 دقيقة."]}'::jsonb);
