insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('harcha', '{"en":"Harcha (semolina griddle bread)","fr":"Harcha (galette de semoule)","ar":"الحرشة"}'::jsonb, true, 'bread', array['breakfast','snack']::text[], 8, '{"en":"1 harcha (≈80 g)","fr":"1 harcha (≈80 g)","ar":"حرشة واحدة (≈80 غ)"}'::jsonb, 15, 20, false, null, null, null, '{"en":["Mix semolina, sugar, salt and baking powder; rub in the melted butter.","Add milk gradually to form a soft dough; rest 10 minutes.","Shape small discs, roll in semolina and cook on a low-heat pan 8–10 minutes per side."],"fr":["Mélanger semoule, sucre, sel et levure chimique ; incorporer le beurre fondu.","Ajouter le lait progressivement pour obtenir une pâte souple ; repos 10 minutes.","Former des galettes, les rouler dans la semoule et cuire à feu doux 8 à 10 minutes par face."],"ar":["اخلطي السميد والسكر والملح والخميرة الكيميائية، ثم أضيفي الزبدة الذائبة وافركيه.","أضيفي الحليب تدريجيا حتى تحصلي على عجين لين واتركيه 10 دقائق.","شكلي أقراصا صغيرة، مرريها في السميد واطهيها على نار هادئة 8-10 دقائق لكل جهة."]}'::jsonb);
