insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('seffa', '{"en":"Seffa (sweet vermicelli)","fr":"Seffa (vermicelles sucrés)","ar":"السفة بالشعرية"}'::jsonb, true, 'dessert', array['lunch','snack']::text[], 8, '{"en":"1 plate (≈90 g)","fr":"1 assiette (≈90 g)","ar":"صحن (≈90 غ)"}'::jsonb, 10, 30, false, null, null, null, '{"en":["Steam the vermicelli three times, separating it with a little water and butter each time.","Arrange in a dome; decorate with powdered sugar, cinnamon and toasted ground almonds."],"fr":["Cuire les vermicelles à la vapeur trois fois en les aérant avec un peu d’eau et de beurre.","Dresser en dôme ; décorer de sucre glace, cannelle et amandes grillées moulues."],"ar":["فوري الشعرية ثلاث مرات مع تفريقها بقليل من الماء والزبدة كل مرة.","شكليها على شكل قبة وزينيها بالسكر الناعم والقرفة واللوز المحمر المطحون."]}'::jsonb);
