insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('eggs_tomato', '{"en":"Eggs with tomato (bid b’tomatish)","fr":"Œufs à la tomate","ar":"البيض بالطماطم"}'::jsonb, true, 'breakfast', array['breakfast','dinner']::text[], 2, '{"en":"1 portion (≈290 g)","fr":"1 portion (≈290 g)","ar":"حصة (≈290 غ)"}'::jsonb, 5, 15, true, null, null, null, '{"en":["Cook grated tomato, onion, oil and spices for 8–10 minutes.","Crack the eggs into the sauce, cover and cook 4–5 minutes. Add parsley."],"fr":["Cuire tomate râpée, oignon, huile et épices 8 à 10 minutes.","Casser les œufs dans la sauce, couvrir 4 à 5 minutes. Ajouter le persil."],"ar":["اطهي الطماطم المحكوكة مع البصل والزيت والتوابل 8-10 دقائق.","اكسري البيض في المرقة وغطيه 4-5 دقائق ثم المعدنوس."]}'::jsonb);
