insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('moroccan_breakfast_plate', '{"en":"Moroccan-style breakfast plate","fr":"Petit-déjeuner à la marocaine","ar":"فطور مغربي متوازن"}'::jsonb, true, 'breakfast', array['breakfast']::text[], 1, '{"en":"1 plate","fr":"1 assiette","ar":"صحن واحد"}'::jsonb, 10, 10, true, null, null, null, '{"en":["Boil the egg 9 minutes.","Serve with whole-wheat bread, a little olive oil for dipping, olives, sliced tomato, cheese and unsweetened tea."],"fr":["Cuire l’œuf 9 minutes.","Servir avec pain complet, un peu d’huile d’olive, olives, tomate, fromage et thé non sucré."],"ar":["اسلقي البيضة 9 دقائق.","قدميها مع خبز كامل وقليل من زيت الزيتون والزيتون والطماطم والجبن وأتاي بدون سكر."]}'::jsonb);
