insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('mint_tea_sugar', '{"en":"Mint tea (traditional, sweetened)","fr":"Thé à la menthe (traditionnel, sucré)","ar":"أتاي بالنعناع (بالسكر)"}'::jsonb, true, 'drink', array['snack']::text[], 4, '{"en":"1 glass (≈200 ml)","fr":"1 verre (≈200 ml)","ar":"كأس (≈200 مل)"}'::jsonb, 2, 8, false, null, null, '{"en":"Mint leaves are infused and removed, so they are not counted.","fr":"Les feuilles de menthe sont infusées puis retirées : non comptées.","ar":"النعناع ينقع ثم يزال، لذلك لم يحسب."}'::jsonb, '{"en":["Rinse green tea leaves with a little boiling water and discard it.","Add boiling water, mint and sugar; steep 3–5 minutes.","Pour from a height to mix and serve."],"fr":["Rincer le thé vert avec un peu d’eau bouillante et la jeter.","Ajouter l’eau bouillante, la menthe et le sucre ; infuser 3 à 5 minutes.","Verser de haut pour mélanger et servir."],"ar":["اشطفي الأتاي بقليل من الماء المغلي وتخلصي منه.","أضيفي الماء المغلي والنعناع والسكر واتركيه 3-5 دقائق.","صبيه من الأعلى ليختلط وقدميه."]}'::jsonb);
