insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('chicken_brochettes', '{"en":"Chicken brochettes","fr":"Brochettes de poulet","ar":"القطبان بالدجاج"}'::jsonb, true, 'main', array['lunch','dinner']::text[], 4, '{"en":"2 skewers (≈170 g)","fr":"2 brochettes (≈170 g)","ar":"قضيبان (≈170 غ)"}'::jsonb, 15, 15, false, null, null, null, '{"en":["Cut chicken into cubes and marinate with grated onion, garlic, spices, parsley, lemon juice and oil for at least 30 minutes.","Thread onto skewers and grill 12–15 minutes, turning regularly."],"fr":["Couper le poulet en cubes et mariner avec oignon râpé, ail, épices, persil, citron et huile au moins 30 minutes.","Enfiler sur des brochettes et griller 12 à 15 minutes en retournant."],"ar":["قطعي الدجاج مكعبات وتبليه بالبصل المحكوك والثوم والتوابل والمعدنوس والحامض والزيت 30 دقيقة على الأقل.","ادخليه في القضبان واشويه 12-15 دقيقة مع التقليب."]}'::jsonb);
