insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('chickpea_soup', '{"en":"Chickpea & vegetable soup","fr":"Soupe de pois chiches et légumes","ar":"حساء الحمص والخضر"}'::jsonb, true, 'soup', array['lunch','dinner']::text[], 4, '{"en":"1 bowl (≈350 ml)","fr":"1 bol (≈350 ml)","ar":"زلافة (≈350 مل)"}'::jsonb, 15, 60, true, null, null, null, '{"en":["Soak chickpeas overnight.","Cook all ingredients with 1.5 L water for 50–60 minutes.","Blend partly for a creamy texture and serve with coriander."],"fr":["Faire tremper les pois chiches la veille.","Cuire tous les ingrédients avec 1,5 L d’eau 50 à 60 minutes.","Mixer en partie pour une texture onctueuse et servir avec la coriandre."],"ar":["انقعي الحمص من الليلة السابقة.","اطهي جميع المكونات مع 1.5 لتر ماء 50-60 دقيقة.","اطحني جزءا منه ليصبح كريميا وقدميه بالقزبور."]}'::jsonb);
