insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('vegetable_soup', '{"en":"Moroccan vegetable soup (chorba)","fr":"Soupe de légumes (chorba)","ar":"شربة الخضر"}'::jsonb, true, 'soup', array['lunch','dinner']::text[], 4, '{"en":"1 bowl (≈350 ml)","fr":"1 bol (≈350 ml)","ar":"زلافة (≈350 مل)"}'::jsonb, 15, 30, true, null, null, null, '{"en":["Peel and chop all vegetables.","Cook with oil, salt and 1.2 L water for 25–30 minutes.","Blend and finish with parsley."],"fr":["Éplucher et couper tous les légumes.","Cuire avec huile, sel et 1,2 L d’eau 25 à 30 minutes.","Mixer et finir avec le persil."],"ar":["قشري وقطعي جميع الخضر.","اطهيها مع الزيت والملح و1.2 لتر ماء 25-30 دقيقة.","اطحنيها وزينيها بالمعدنوس."]}'::jsonb);
