insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('potato_tomato_eggs', '{"en":"Potato, tomato & onion skillet with eggs","fr":"Poêlée pommes de terre, tomates, oignon et œufs","ar":"مقلاة البطاطس والطماطم والبصل بالبيض"}'::jsonb, false, 'main', array['breakfast','lunch','dinner']::text[], 2, '{"en":"1 portion (≈410 g)","fr":"1 portion (≈410 g)","ar":"حصة (≈410 غ)"}'::jsonb, 10, 20, true, null, null, null, '{"en":["Dice potatoes and cook in the oil with onion, covered, 10–12 minutes.","Add diced tomato and spices; cook 5 minutes.","Make 4 wells, crack in the eggs, cover and cook until set."],"fr":["Couper les pommes de terre en dés et les cuire dans l’huile avec l’oignon, à couvert, 10 à 12 minutes.","Ajouter la tomate et les épices ; cuire 5 minutes.","Faire 4 puits, casser les œufs, couvrir jusqu’à ce qu’ils prennent."],"ar":["قطعي البطاطس مكعبات واطهيها في الزيت مع البصل مغطاة 10-12 دقيقة.","أضيفي الطماطم والتوابل 5 دقائق.","اعملي 4 حفر واكسري البيض وغطيه حتى ينضج."]}'::jsonb);
