insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('tortilla', '{"en":"Potato omelette (tortilla)","fr":"Omelette aux pommes de terre (tortilla)","ar":"عجة البطاطس"}'::jsonb, false, 'main', array['lunch','dinner']::text[], 3, '{"en":"1/3 omelette (≈220 g)","fr":"1/3 d’omelette (≈220 g)","ar":"ثلث العجة (≈220 غ)"}'::jsonb, 10, 25, true, null, null, null, '{"en":["Slice potatoes and onion thinly; cook gently in oil, covered, until soft (15 minutes).","Beat eggs with salt, mix with the potatoes.","Cook in the pan 5 minutes, flip using a plate and cook 3 more minutes."],"fr":["Émincer pommes de terre et oignon ; cuire doucement à couvert dans l’huile (15 minutes).","Battre les œufs avec le sel et mélanger aux pommes de terre.","Cuire 5 minutes, retourner à l’aide d’une assiette et cuire encore 3 minutes."],"ar":["قطعي البطاطس والبصل شرائح رقيقة واطهيها في الزيت مغطاة حتى تلين (15 دقيقة).","اخفقي البيض مع الملح واخلطيه مع البطاطس.","اطهيها 5 دقائق ثم اقلبيها بصحن واتركيها 3 دقائق."]}'::jsonb);
