insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('spinach_omelette', '{"en":"Spinach & feta omelette","fr":"Omelette épinards et feta","ar":"عجة بالسبانخ والفيتا"}'::jsonb, false, 'breakfast', array['breakfast','dinner']::text[], 1, '{"en":"1 omelette (≈245 g)","fr":"1 omelette (≈245 g)","ar":"عجة واحدة (≈245 غ)"}'::jsonb, 5, 6, false, null, null, null, '{"en":["Wilt spinach in the oil 1 minute.","Pour in beaten eggs, add crumbled feta and cook until set; fold."],"fr":["Faire tomber les épinards dans l’huile 1 minute.","Verser les œufs battus, ajouter la feta émiettée et cuire ; plier."],"ar":["شوحي السبانخ في الزيت دقيقة واحدة.","أضيفي البيض المخفوق والفيتا المفتتة حتى ينضج ثم اطويها."]}'::jsonb);
