insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('harira_veg', '{"en":"Harira (vegetarian)","fr":"Harira (végétarienne)","ar":"الحريرة (بدون لحم)"}'::jsonb, true, 'soup', array['dinner','lunch']::text[], 6, '{"en":"1 bowl (≈350 ml)","fr":"1 bol (≈350 ml)","ar":"زلافة واحدة (≈350 مل)"}'::jsonb, 20, 60, true, 'harira', '{"en":"Vegetarian","fr":"Végétarienne","ar":"نباتية"}'::jsonb, null, '{"en":["Soak the chickpeas overnight.","Sauté onion, celery, herbs and spices in oil for 5 minutes.","Add tomatoes, tomato paste, chickpeas, lentils and 2.5 L water; simmer 50 minutes.","Thicken with the flour mixed in cold water, add vermicelli and cook 8–10 minutes."],"fr":["Faire tremper les pois chiches la veille.","Faire revenir oignon, céleri, herbes et épices dans l’huile 5 minutes.","Ajouter tomates, concentré, pois chiches, lentilles et 2,5 L d’eau ; mijoter 50 minutes.","Épaissir avec la farine délayée dans l’eau froide, ajouter les vermicelles et cuire 8 à 10 minutes."],"ar":["انقعي الحمص من الليلة السابقة.","شوحي البصل والكرافس والأعشاب والتوابل في الزيت 5 دقائق.","أضيفي الطماطم والمعجون والحمص والعدس و2.5 لتر ماء، واتركيها 50 دقيقة.","ثخني بالتدويرة ثم أضيفي الشعرية لمدة 8 إلى 10 دقائق."]}'::jsonb);
