insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('bissara_peas', '{"en":"Bissara with split peas","fr":"Bissara aux pois cassés","ar":"بيصارة بالجلبانة المقشرة"}'::jsonb, true, 'soup', array['breakfast','dinner']::text[], 4, '{"en":"1 bowl (≈300 ml)","fr":"1 bol (≈300 ml)","ar":"زلافة (≈300 مل)"}'::jsonb, 10, 45, true, 'bissara', '{"en":"Split peas","fr":"Pois cassés","ar":"بالجلبانة المقشرة"}'::jsonb, '{"en":"Uses the USDA value for cooked split peas (700 g cooked ≈ 280 g dry).","fr":"Valeur USDA des pois cassés cuits (700 g cuits ≈ 280 g secs).","ar":"محسوبة بقيمة الجلبانة المطبوخة (700 غ مطبوخة ≈ 280 غ جافة)."}'::jsonb, '{"en":["Cook the split peas with garlic in water until soft.","Blend, season and thin with hot water.","Serve with olive oil, cumin and paprika."],"fr":["Cuire les pois cassés avec l’ail dans l’eau jusqu’à tendreté.","Mixer, assaisonner et allonger avec de l’eau chaude.","Servir avec huile d’olive, cumin et paprika."],"ar":["اطهي الجلبانة المقشرة مع الثوم في الماء حتى تنضج.","اطحنيها وتبليها وخففيها بالماء الساخن.","تقدم مع زيت الزيتون والكمون والتحميرة."]}'::jsonb);
