insert into public.recipes (id, name, moroccan, kind, meals, servings, serving, prep_min, cook_min, budget, variant_of, variant, note, steps) values ('couscous_veg', '{"en":"Vegetable couscous (vegetarian)","fr":"Couscous aux légumes (végétarien)","ar":"كسكس بالخضر (نباتي)"}'::jsonb, true, 'main', array['lunch']::text[], 6, '{"en":"1 plate (≈450 g)","fr":"1 assiette (≈450 g)","ar":"صحن (≈450 غ)"}'::jsonb, 30, 60, true, 'couscous_beef', '{"en":"Vegetarian","fr":"Végétarien","ar":"نباتي"}'::jsonb, null, '{"en":["Cook onion, tomato, spices, oil and soaked chickpeas in 2 L water for 30 minutes.","Add the vegetables in order of cooking time (carrots, turnips, cabbage, then zucchini and pumpkin).","Steam the couscous three times over the broth and serve with the vegetables."],"fr":["Cuire oignon, tomate, épices, huile et pois chiches trempés dans 2 L d’eau pendant 30 minutes.","Ajouter les légumes selon leur temps de cuisson (carottes, navets, chou, puis courgettes et potiron).","Cuire la semoule trois fois à la vapeur et servir avec les légumes."],"ar":["اطهي البصل والطماطم والتوابل والزيت والحمص المنقوع في 2 لتر ماء لمدة 30 دقيقة.","أضيفي الخضر حسب مدة طهيها (الجزر، اللفت، الكرنب، ثم الكوسة والكرعة).","فوري الكسكس ثلاث مرات وقدميه مع الخضر."]}'::jsonb);
